import { useForm } from '@inertiajs/react';
import { useMemo } from 'react';
import { Check, PhoneField, SelectField, TextArea, TextField } from '@/components/ui/Fields';

export type PropertyType = { slug: string; name: string; group: string; column: string };

export type ClinicProfile = Record<string, unknown> & {
    id?: number;
    name?: string;
    specialty_ids?: number[];
    payment_methods?: string[];
    achievements?: string[];
};

export interface ClinicProfileOptions {
    cities: { id: number; name: string }[];
    districts: { id: number; city_id: number; name: string }[];
    specialties: { id: number; name: string }[];
    payments: string[];
    propertyTypes: PropertyType[];
}

/** Состояние формы профиля клиники; extra — дополнительные поля конкретной страницы (например, организация в админке). */
export function useClinicProfileForm(profile: ClinicProfile | null, propertyTypes: PropertyType[], extra: Record<string, unknown> = {}) {
    const b = profile ?? {};
    const propertyDefaults = Object.fromEntries(propertyTypes.map((p) => [p.column, Boolean(b[p.column])]));

    const form = useForm<Record<string, any>>({
        name: (b.name as string) ?? '',
        tagline: (b.tagline as string) ?? '',
        description: (b.description as string) ?? '',
        city_id: (b.city_id as number) ?? '',
        district_id: (b.district_id as number) ?? '',
        address: (b.address as string) ?? '',
        metro: (b.metro as string) ?? '',
        directions_note: (b.directions_note as string) ?? '',
        parking: (b.parking as string) ?? '',
        warranty: (b.warranty as string) ?? '',
        lat: (b.lat as number) ?? '',
        lng: (b.lng as number) ?? '',
        phone: (b.phone as string) ?? '',
        email: (b.email as string) ?? '',
        website: (b.website as string) ?? '',
        founded_year: (b.founded_year as number) ?? '',
        license_number: (b.license_number as string) ?? '',
        license_issuer: (b.license_issuer as string) ?? '',
        license_date: (b.license_date as string) ?? '',
        restrictions: (b.restrictions as string) ?? '',
        payment_methods: (b.payment_methods as string[]) ?? [],
        achievements: ((b.achievements as string[]) ?? ['']).join('\n'),
        specialty_ids: ((b.specialty_ids as number[]) ?? []).map(String),
        accepts_children: Boolean(b.accepts_children),
        children_age_from: (b.children_age_from as number) ?? '',
        installment_months: (b.installment_months as number) ?? '',
        ...propertyDefaults,
        ...extra,
    });

    /** Готовит данные к отправке: достижения — списком, направления — числами, пустые координаты — null. */
    const prepare = () => {
        form.transform((data) => ({
            ...data,
            lat: data.lat === '' ? null : data.lat,
            lng: data.lng === '' ? null : data.lng,
            achievements: String(data.achievements).split('\n').map((s: string) => s.trim()).filter(Boolean),
            specialty_ids: data.specialty_ids.map(Number),
        }));
    };

    return { form, prepare };
}

/** Поля профиля клиники: общие для кабинета владельца и админ-панели. */
export default function ClinicProfileFields({
    form,
    options,
    phoneRequired = true,
    showCoordinates = false,
}: {
    form: ReturnType<typeof useClinicProfileForm>['form'];
    options: ClinicProfileOptions;
    phoneRequired?: boolean;
    showCoordinates?: boolean;
}) {
    const { cities, districts, specialties, payments, propertyTypes } = options;
    const propertyGroups = useMemo(() => {
        const groups = new Map<string, PropertyType[]>();
        propertyTypes.forEach((p) => {
            const list = groups.get(p.group) ?? [];
            list.push(p);
            groups.set(p.group, list);
        });
        return [...groups.entries()];
    }, [propertyTypes]);

    const cityDistricts = districts.filter((d) => String(d.city_id) === String(form.data.city_id));
    const togglePay = (p: string) => form.setData('payment_methods', form.data.payment_methods.includes(p) ? form.data.payment_methods.filter((x: string) => x !== p) : [...form.data.payment_methods, p]);
    const toggleSpec = (id: string) => form.setData('specialty_ids', form.data.specialty_ids.includes(id) ? form.data.specialty_ids.filter((x: string) => x !== id) : [...form.data.specialty_ids, id]);

    return (
        <>
            <section className="card form-grid">
                <h2 className="card-title span-2">Основное</h2>
                <TextField className="span-2" label="Название" required value={form.data.name} onChange={(e) => form.setData('name', e.target.value)} error={form.errors.name} />
                <TextField className="span-2" label="Короткий слоган" value={form.data.tagline} onChange={(e) => form.setData('tagline', e.target.value)} error={form.errors.tagline} />
                <TextArea className="span-2" label="Описание" value={form.data.description} maxLength={3000} onChange={(e) => form.setData('description', e.target.value)} error={form.errors.description} />
                <SelectField label="Город" required value={form.data.city_id} onChange={(e) => form.setData('city_id', e.target.value)} error={form.errors.city_id}>
                    <option value="">Выберите</option>
                    {cities.map((c) => (
                        <option key={c.id} value={c.id}>
                            {c.name}
                        </option>
                    ))}
                </SelectField>
                <SelectField label="Район" value={form.data.district_id} onChange={(e) => form.setData('district_id', e.target.value)}>
                    <option value="">Не указан</option>
                    {cityDistricts.map((d) => (
                        <option key={d.id} value={d.id}>
                            {d.name}
                        </option>
                    ))}
                </SelectField>
                <TextField className="span-2" label="Адрес" required value={form.data.address} onChange={(e) => form.setData('address', e.target.value)} error={form.errors.address} />
                <TextField label="Метро" value={form.data.metro} onChange={(e) => form.setData('metro', e.target.value)} />
                <TextField label="Парковка" placeholder="Например: бесплатная у входа" maxLength={160} value={form.data.parking} onChange={(e) => form.setData('parking', e.target.value)} error={form.errors.parking} />
                <TextArea className="span-2" label="Как найти вход" hint="Этаж, вывеска, вход со двора, домофон — это увидят пациенты в блоке «Как добраться»." maxLength={500} value={form.data.directions_note} onChange={(e) => form.setData('directions_note', e.target.value)} error={form.errors.directions_note} />
                <PhoneField label="Телефон" required={phoneRequired} value={form.data.phone} onChange={(e) => form.setData('phone', e.target.value)} error={form.errors.phone} />
                <TextField label="E-mail" type="email" value={form.data.email} onChange={(e) => form.setData('email', e.target.value)} error={form.errors.email} />
                <TextField label="Сайт" value={form.data.website} placeholder="https://" onChange={(e) => form.setData('website', e.target.value)} error={form.errors.website} />
                {showCoordinates ? (
                    <>
                        <TextField label="Широта" inputMode="decimal" value={form.data.lat ?? ''} onChange={(e) => form.setData('lat', e.target.value)} error={form.errors.lat} />
                        <TextField label="Долгота" inputMode="decimal" value={form.data.lng ?? ''} onChange={(e) => form.setData('lng', e.target.value)} error={form.errors.lng} />
                    </>
                ) : null}
            </section>

            <section className="card form-grid">
                <h2 className="card-title span-2">Лицензия и документы</h2>
                <TextField label="Год основания" type="number" value={form.data.founded_year} onChange={(e) => form.setData('founded_year', e.target.value)} error={form.errors.founded_year} />
                <TextField label="Номер лицензии" value={form.data.license_number} onChange={(e) => form.setData('license_number', e.target.value)} />
                <TextField label="Кем выдана" value={form.data.license_issuer} onChange={(e) => form.setData('license_issuer', e.target.value)} />
                <TextField label="Дата лицензии" type="date" value={form.data.license_date} onChange={(e) => form.setData('license_date', e.target.value)} error={form.errors.license_date} />
                <TextArea className="span-2" label="Ограничения приёма" hint="Например: не принимаем детей младше 3 лет, нет наркоза." value={form.data.restrictions} onChange={(e) => form.setData('restrictions', e.target.value)} />
                <TextArea className="span-2" label="Гарантии" hint="Например: пломбы — 1 год, коронки — 3 года, импланты — пожизненно от производителя. Условия гарантии." maxLength={1500} value={form.data.warranty} onChange={(e) => form.setData('warranty', e.target.value)} error={form.errors.warranty} />
                <TextArea className="span-2" label="Достижения (каждое с новой строки)" value={form.data.achievements} onChange={(e) => form.setData('achievements', e.target.value)} />
            </section>

            <section className="card stack">
                <h2 className="card-title">Направления</h2>
                <div className="check-grid">
                    {specialties.map((s) => (
                        <Check key={s.id} label={s.name} checked={form.data.specialty_ids.includes(String(s.id))} onChange={() => toggleSpec(String(s.id))} />
                    ))}
                </div>
            </section>

            <section className="card stack">
                <h2 className="card-title">Условия и свойства</h2>
                <div className="check-grid">
                    <Check label="Детский приём" checked={form.data.accepts_children} onChange={(e) => form.setData('accepts_children', e.target.checked)} />
                </div>
                {form.data.accepts_children ? (
                    <TextField label="Дети с какого возраста" type="number" value={form.data.children_age_from} onChange={(e) => form.setData('children_age_from', e.target.value)} />
                ) : null}
                {propertyGroups.map(([group, items]) => (
                    <div key={group} className="stack">
                        <h3 className="text-sm text-muted">{group}</h3>
                        <div className="check-grid">
                            {items.map((p) => (
                                <Check key={p.slug} label={p.name} checked={Boolean(form.data[p.column])} onChange={(e) => form.setData(p.column, e.target.checked)} />
                            ))}
                        </div>
                    </div>
                ))}
                {form.data.has_installment ? (
                    <TextField label="Рассрочка, мес." type="number" value={form.data.installment_months} onChange={(e) => form.setData('installment_months', e.target.value)} />
                ) : null}
                <h3 className="text-sm text-muted">Оплата</h3>
                <div className="check-grid">
                    {payments.map((p) => (
                        <Check key={p} label={p} checked={form.data.payment_methods.includes(p)} onChange={() => togglePay(p)} />
                    ))}
                </div>
            </section>
        </>
    );
}
